grammar.example:
// 1. let과 const의 블록 스코프
{
    let blockScoped = "블록 내부만 접근 가능";
    const pi = 3.141592;
    // pi = 3.14; // TypeError: Assignment to constant variable.
}
// console.log(blockScoped); // ReferenceError!

// 2. const로 선언된 객체의 내부 프로퍼티는 변경 가능
const user = { name: "철수", age: 20 };
user.age = 21; // 가능! (참조 주소는 그대로이며 내부 속성만 변경)
console.log(user); // { name: "철수", age: 21 }

// 3. TDZ (Temporal Dead Zone, 일시적 사각지대)
// let/const도 호이스팅되지만 초기화 전까지 TDZ에 머물러 접근 시 에러 발생
// console.log(temp); // ReferenceError: Cannot access 'temp' before initialization
let temp = "초기화 완료";

// 7대 원시 타입
const num = 42;                    // Number
const str = "Hello";               // String
const bool = true;                 // Boolean
const undef = undefined;           // Undefined (값이 할당되지 않음)
const nul = null;                  // Null (의도적인 빈 값)
const sym = Symbol("id");          // Symbol (유일무이한 고유 식별자)
const big = 9007199254740991n;     // BigInt (임의 정밀도 정수)

// typeof 검사
console.log(typeof num);   // "number"
console.log(typeof str);   // "string"
console.log(typeof undef); // "undefined"
console.log(typeof sym);   // "symbol"
console.log(typeof big);   // "bigint"
console.log(typeof nul);   // "object" (유명한 JS 초기 설계 버그!)

// 정확한 null 및 배열 검사법
console.log(nul === null);                // true
console.log(Array.isArray([1, 2, 3]));    // true

// 1. == vs ===
console.log(0 == false);   // true (암묵적 형변환!)
console.log(0 === false);  // false (타입이 다름: number vs boolean)
console.log(null == undefined);  // true
console.log(null === undefined); // false

// 2. 단축 평가 (Short-circuit Evaluation)
const isLogged = true;
isLogged && console.log("로그인된 사용자입니다."); // 앞이 참일 때 뒤 실행

// 3. 널 병합 연산자 (??) vs 논리 OR (||)
const count = 0;
const qty1 = count || 10;  // 10 (0은 Falsy이므로 뒤로 넘어감, 원치 않는 버그!)
const qty2 = count ?? 10;  // 0 (0은 유효한 값이므로 그대로 채택!)

// 4. 옵셔널 체이닝 (?.)
const user = { name: "민수", profile: null };
// user.profile.bio; // TypeError: Cannot read properties of null
console.log(user.profile?.bio); // undefined (에러 없이 안전!)

grammar.syntax:
if (condition) { ... } else if (other) { ... } else { ... }
const result = condition ? valIfTrue : valIfFalse;
switch (expr) { case val: ...; break; default: ...; }

grammar.example:
const score = 85;

// if-else 분기문
let grade = "";
if (score >= 90) {
    grade = "A";
} else if (score >= 80) {
    grade = "B";
} else {
    grade = "C";
}

// 삼항 연산자 (Ternary Operator)
const status = score >= 60 ? "합격" : "불합격";
console.log(`성적: ${grade}, 결과: ${status}`);

// switch-case 분기
const fruit = "apple";
switch (fruit) {
    case "banana":
        console.log("바나나 2,000원");
        break;
    case "apple":
        console.log("사과 3,000원");
        break;
    default:
        console.log("품목 없음");
        break;
}

const colors = ["빨강", "초록", "파랑"];

// 1. for...of: 배열의 '값(Element)'을 직접 순회
for (const color of colors) {
    console.log(color); // "빨강", "초록", "파랑"
}

// 2. for...in: 객체의 '열거 가능한 키(Key)'를 순회
const car = { brand: "현대", model: "아이오닉", year: 2024 };
for (const key in car) {
    console.log(`${key}: ${car[key]}`);
}

// 3. 인덱스와 값이 모두 필요한 경우 entries() 활용
for (const [index, color] of colors.entries()) {
    console.log(`[${index}] = ${color}`);
}

grammar.syntax:
function foo() { ... }           // 함수 선언식 (호이스팅 지원)
const bar = function() { ... };  // 함수 표현식
const baz = (a, b) => a + b;     // 화살표 함수 (간결, lexical this)

grammar.example:
// 1. 화살표 함수의 간결한 단축 문법
const add = (a, b) => a + b;
const square = x => x * x;
console.log(add(5, 3)); // 8

// 2. 일반 함수 vs 화살표 함수의 this 차이
const timer = {
    name: "타이머 객체",
    regular: function() {
        console.log("일반 함수 this:", this.name);
    },
    arrow: () => {
        // 화살표 함수 내부의 this는 전역(window 또는 undefined)을 가리킴
        console.log("화살표 함수 this:", typeof this);
    },
    startDelayed() {
        // setTimeout 콜백에서 화살표 함수를 쓰면 timer 객체의 this를 안전하게 유지!
        setTimeout(() => {
            console.log("지연 실행 this:", this.name); // "타이머 객체"
        }, 100);
    }
};

timer.regular();
timer.arrow();
timer.startDelayed();

grammar.syntax:
function outer() {
    let count = 0;
    return function inner() { count++; return count; };
}

grammar.example:
function createCounter(initialValue = 0) {
    let privateCount = initialValue; // 외부에서 직접 접근할 수 없는 비공개 변수

    return {
        increment() {
            privateCount++;
            return privateCount;
        },
        decrement() {
            privateCount--;
            return privateCount;
        },
        getValue() {
            return privateCount;
        }
    };
}

const counter = createCounter(10);
console.log(counter.increment()); // 11
console.log(counter.increment()); // 12
console.log(counter.decrement()); // 11
console.log(counter.privateCount); // undefined (완벽한 은닉화!)

