grammar.example:
// 1. 객체 구조 분해와 기본값, 별칭 할당
const config = { host: "localhost", port: 8080 };
const { host, port, timeout = 3000 } = config;
const { host: serverHost } = config; // 별칭 serverHost로 꺼내기
console.log(serverHost, timeout); // "localhost", 3000

// 2. 스프레드 연산자를 통한 얕은 복사 및 병합
const baseUser = { id: 1, role: "user" };
const adminUser = { ...baseUser, role: "admin", level: 99 };
console.log(adminUser); // { id: 1, role: "admin", level: 99 }

// 3. 레스트 파라미터 (Rest Parameter)
function sumAll(...numbers) {
    return numbers.reduce((acc, cur) => acc + cur, 0);
}
console.log(sumAll(10, 20, 30, 40)); // 100

const products = [
    { id: 1, name: "노트북", price: 1200000, inStock: true },
    { id: 2, name: "마우스", price: 35000, inStock: false },
    { id: 3, name: "키보드", price: 89000, inStock: true },
    { id: 4, name: "모니터", price: 350000, inStock: true }
];

// 1. filter: 재고가 있는 상품만 선별
const available = products.filter(p => p.inStock);

// 2. map: 상품 이름 목록만 추출
const names = available.map(p => p.name);
console.log(names); // ["노트북", "키보드", "모니터"]

// 3. reduce: 재고 상품의 총 금액 합산
const totalPrice = available.reduce((acc, cur) => acc + cur.price, 0);
console.log(`총 재고 가치: ${totalPrice.toLocaleString()}원`);

// 4. find: 특정 조건의 첫 번째 원소 검색
const mouse = products.find(p => p.name === "마우스");
console.log(mouse.price); // 35000

// 프로토타입 기반의 상속 원리
const animal = {
    isAlive: true,
    eat() {
        console.log("음식을 먹습니다.");
    }
};

// animal을 프로토타입으로 갖는 rabbit 객체 생성
const rabbit = Object.create(animal);
rabbit.jump = function() {
    console.log("깡충 뛰어오릅니다!");
};

rabbit.eat();  // 부모(animal)의 프로토타입 체인을 통해 발견되어 실행!
rabbit.jump(); // 자신의 메서드 실행

console.log(rabbit.hasOwnProperty("jump")); // true (직접 소유)
console.log(rabbit.hasOwnProperty("eat"));  // false (프로토타입 체인 상속)
console.log(Object.getPrototypeOf(rabbit) === animal); // true

