grammar.example:
class Vehicle {
    #serialNumber; // 진정한 비공개(Private) 필드 (외부 접근 차단)

    constructor(brand, serial) {
        this.brand = brand;
        this.#serialNumber = serial;
    }

    getInfo() {
        return `브랜드: ${this.brand} (시리얼: ${this.#serialNumber})`;
    }

    static compare(a, b) {
        return a.brand.localeCompare(b.brand);
    }
}

class ElectricCar extends Vehicle {
    constructor(brand, serial, batteryCapacity) {
        super(brand, serial); // 부모 생성자 호출 필수
        this.batteryCapacity = batteryCapacity;
    }

    charge() {
        console.log(`${this.brand} 배터리(${this.batteryCapacity}kWh) 충전 중...`);
    }
}

const tesla = new ElectricCar("Tesla", "TS-9981", 75);
tesla.charge();
console.log(tesla.getInfo());
// console.log(tesla.#serialNumber); // SyntaxError: Private field '#serialNumber' must be declared in an enclosing class

console.log("1. 동기 코드 시작");

// 매크로태스크 (Task Queue)
setTimeout(() => {
    console.log("5. setTimeout (매크로태스크)");
}, 0);

// 마이크로태스크 (Microtask Queue)
Promise.resolve().then(() => {
    console.log("3. Promise .then() (마이크로태스크)");
}).then(() => {
    console.log("4. 연결된 마이크로태스크");
});

console.log("2. 동기 코드 종료");

// 출력 순서:
// 1. 동기 코드 시작
// 2. 동기 코드 종료
// 3. Promise .then() (마이크로태스크)
// 4. 연결된 마이크로태스크
// 5. setTimeout (매크로태스크)

function fetchUserData(userId) {
    return new Promise((resolve, reject) => {
        if (!userId) {
            reject(new Error("유효하지 않은 사용자 ID입니다."));
            return;
        }
        setTimeout(() => {
            resolve({ id: userId, name: "홍길동", role: "Developer" });
        }, 300);
    });
}

fetchUserData(1)
    .then(user => {
        console.log("조회 성공:", user.name);
        return user.role; // 다음 체인으로 값 전달
    })
    .then(role => {
        console.log("직무:", role);
    })
    .catch(error => {
        console.error("에러 발생:", error.message);
    })
    .finally(() => {
        console.log("비동기 처리 완료 (성공/실패 무관하게 항상 실행)");
    });

