grammar.example:
const delay = ms => new Promise(res => setTimeout(res, ms));

async function fetchAllData() {
    try {
        console.log("데이터 요청 중...");
        await delay(500); // 500ms 동안 비동기 일시 정지 (블로킹 아님)

        const res = { status: 200, data: ["자바스크립트", "타입스크립트"] };
        if (res.status !== 200) {
            throw new Error("서버 응답 오류");
        }

        return res.data;
    } catch (err) {
        console.error("데이터 로드 실패:", err.message);
        return [];
    }
}

// 2개 이상의 독립 비동기 작업을 병렬로 처리할 때: Promise.all()
async function runParallel() {
    const start = Date.now();
    const [d1, d2] = await Promise.all([
        delay(300).then(() => "A"),
        delay(300).then(() => "B")
    ]);
    console.log(`병렬 완료(${Date.now() - start}ms): ${d1}, ${d2}`);
}

fetchAllData().then(data => console.log("결과:", data));
runParallel();

