grammar.example:
// [math.js] 파일
export const PI = 3.141592;

export function add(a, b) {
    return a + b;
}

// 기본 내보내기 (모듈당 단 하나만 존재 가능)
export default function multiply(a, b) {
    return a * b;
}

// [main.js] 파일
// default export는 중괄호 없이 임의의 이름으로 가져올 수 있음
import multiply, { PI, add as sum } from "./math.js";

console.log(PI);          // 3.141592
console.log(sum(5, 7));   // 12
console.log(multiply(3, 4)); // 12

// 동적 임포트 (코드 스플리팅)
async function loadChartModule() {
    const { renderChart } = await import("./chart.js");
    renderChart();
}

const userSettings = {
    theme: "dark",
    fontSize: 16,
    notifications: true,
    lastVisited: new Date()
};

// 1. JSON 직렬화 (문자열 변환)
const jsonString = JSON.stringify(userSettings, null, 2);
console.log("JSON 출력:\n" + jsonString);

// 2. JSON 역직렬화 (객체 복원)
const parsedData = JSON.parse(jsonString);
console.log("복원된 테마:", parsedData.theme);

// 3. Web Storage API (localStorage) 활용
function saveState(key, data) {
    localStorage.setItem(key, JSON.stringify(data));
}

function loadState(key) {
    const raw = localStorage.getItem(key);
    return raw ? JSON.parse(raw) : null;
}

